// Generated by ../../../rebuild.py; one topology per leaf.
use rand::{Rng, rngs::StdRng};
use std::f64::consts::PI;

fn pick(rng: &mut StdRng, values: &[f64]) -> f64 {
    values[rng.random_range(0..values.len())]
}

pub fn generate(rng: &mut StdRng) -> String {
    let r1 = pick(rng, &[1000.0, 2200.0, 4700.0, 10000.0]);
    let r2 = pick(rng, &[1000.0, 3300.0, 6800.0, 10000.0]);
    let c1 = pick(rng, &[10e-9, 47e-9, 100e-9, 1e-6]);
    let c2 = c1 * pick(rng, &[0.1, 0.5, 1.0, 2.0]);
    let a = r1 * c1 + r1 * c2 + r2 * c2;
    let b = r1 * r2 * c1 * c2;
    let root = (a * a - 4.0 * b).sqrt();
    let slow_tau = (a + root) / 2.0;
    let fast_tau = 2.0 * b / (a + root);
    let low = 1.0 / (2.0 * PI * slow_tau);
    let high = 1.0 / (2.0 * PI * fast_tau);
    format!(
        "Unbuffered two-stage RC low-pass ladder\n* Ideal voltage source; unloaded output; interstage loading included.\n* H(s)=1/(1+a*s+b*s^2); a={a:.5e} s, b={b:.5e} s^2.\n* Real pole frequencies {low:.5e} and {high:.5e} Hz.\nV1 in 0 DC 1 AC 1\nR1 in mid {r1:.5e}\nC1 mid 0 {c1:.5e}\nR2 mid out {r2:.5e}\nC2 out 0 {c2:.5e}\n.op\n.ac dec 40 {:.5e} {:.5e}\n.print ac vm(out) vp(out)\n.end",
        low / 100.0,
        high * 100.0
    )
}

#[cfg(test)]
mod validate;

#[cfg(test)]
mod tests {
    use super::*;
    use rand::SeedableRng;

    #[test]
    fn independent_nodal_analysis_matches_topology() {
        let mut rng = StdRng::seed_from_u64(47);
        for _ in 0..200 {
            validate::verify(&generate(&mut rng), "rc-dual-low-pass");
        }
    }
}
